#!/usr/bin/env bash
set -e
sudo chown -R root:root /opt/flavorflow/server/data; sudo chmod 755 /opt/flavorflow/server/data; sudo chmod 664 /opt/flavorflow/server/data/erp.db; sudo rm -f /opt/flavorflow/server/data/erp.db-wal /opt/flavorflow/server/data/erp.db-shm; for f in /etc/nginx/sites-enabled/*; do sudo grep -q "gdfoods" "$f" 2>/dev/null && sudo mv "$f" "$f.bak-$(date +%s)" || true; done; GD=$(sudo grep -R "gdfoods.duckdns.org" /etc/nginx/ -l 2>/dev/null | head -n1); [ -n "$GD" ] && sudo mv "$GD" "$GD.bak-$(date +%s)" || true; sudo mkdir -p /etc/letsencrypt/live/gdfoods.duckdns.org/; [ ! -f /etc/letsencrypt/live/gdfoods.duckdns.org/fullchain.pem ] && sudo openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/letsencrypt/live/gdfoods.duckdns.org/privkey.pem -out /etc/letsencrypt/live/gdfoods.duckdns.org/fullchain.pem -subj "/CN=gdfoods.duckdns.org" 2>/dev/null || true; sudo nginx -t; sudo systemctl restart nginx; sudo systemctl restart flavorflow; sleep 5; echo "=== flavorflow ==="; sudo systemctl status flavorflow --no-pager -l | tail -n 20; echo "=== nginx ==="; sudo systemctl status nginx --no-pager -l | tail -n 20; echo "=== health ==="; curl -s http://127.0.0.1:4000/api/health || echo "health fail"; echo "=== DONE ==="
